{t:"G",title:"Can / can't",intro:"<b>can</b> exprime la capacité, la possibilité et sert aussi à demander ou proposer poliment.",formsTitle:"Formes de can",forms:[["affirmatif","I can swim"],["négatif","I can't (cannot) swim"],["question","Can you swim?"],["après can","verbe SANS to"],["toutes personnes","he can, we can (invariable)"]],sections:[{h:"Toujours + verbe à la base",body:"Après can, jamais de « to » : <b>I can swim</b> (pas « I can to swim »). can ne change pas : he can, she can, we can."},{h:"Demander & proposer",body:"<b>Can you help me?</b> (peux-tu…?), <b>Can I open the window?</b> (puis-je…?). C'est plus direct que « could » (plus poli)."}],examples:[["I can speak English.","Je sais parler anglais."],["She can't come tonight.","Elle ne peut pas venir ce soir."],["Can you help me?","Peux-tu m'aider ?"],["He can drive a car.","Il sait conduire une voiture."],["We can meet tomorrow.","On peut se voir demain."],["Can I ask a question?","Puis-je poser une question ?"]],pitfalls:["« I can to swim » est faux → I can swim.","can ne prend jamais de -s : « he cans » est faux."],keypoints:["can = pouvoir / savoir faire.","Négatif : can't.","can + verbe sans to, invariable."],drills:[{q:"I ___ swim very well.",options:["can","can to","cans"],answer:"can",exp:""},{q:"She ___ come today.",options:["can't","doesn't can","not can"],answer:"can't",exp:""},{q:"___ you help me?",options:["Can","Do can","Are can"],answer:"Can",exp:""},{q:"He can ___ a car.",options:["drive","drives","to drive"],answer:"drive",exp:"Après can : base sans to."}],practice:[{en:"I can swim very well.",fr:"Je sais très bien nager.",hint:"swim"},{en:"She can speak three languages.",fr:"Elle parle trois langues.",hint:"speak"},{en:"Can you open the window?",fr:"Peux-tu ouvrir la fenêtre ?",hint:"window"},{en:"He can't drive yet.",fr:"Il ne sait pas encore conduire.",hint:"drive"},{en:"We can meet tomorrow.",fr:"Nous pouvons nous voir demain.",hint:"meet"},{en:"Can I ask a question?",fr:"Puis-je poser une question ?",hint:"question"},{en:"They can't come today.",fr:"Ils ne peuvent pas venir aujourd'hui.",hint:"today"},{en:"My dog can jump high.",fr:"Mon chien saute haut.",hint:"jump"},{en:"Can you hear me?",fr:"Tu m'entends ?",hint:"hear"},{en:"I can cook pasta.",fr:"Je sais cuisiner des pâtes.",hint:"cook"}]}
